/**
 * NocoDB Node - Version 4
 * Discriminator: resource=row, operation=search
 */


interface Credentials {
  nocoDb: CredentialReference;
  nocoDbApiToken: CredentialReference;
}

/** Search for specific records or list all */
export type NocoDbV4RowSearchParams = {
  resource: 'row';
  operation: 'search';
  authentication?: 'nocoDbApiToken' | 'nocoDb' | Expression<string>;
/**
 * Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
 * @searchListMethod getWorkspaces
 * @default {"mode":"list","value":""}
 */
    workspaceId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
 * @searchListMethod getBases
 * @default {"mode":"list","value":""}
 */
    projectId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The table to operate on. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
 * @searchListMethod getTables
 * @default {"mode":"list","value":""}
 */
    table?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 50
 */
    limit?: number | Expression<number>;
/**
 * Whether the attachment fields defined in 'Download Fields' will be downloaded
 * @default false
 */
    downloadAttachments?: boolean | Expression<boolean>;
/**
 * Names of the fields of type 'attachment' that should be downloaded. Choose from the list, or specify IDs using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
 * @loadOptionsMethod getDownloadFields
 * @displayOptions.show { downloadAttachments: [true] }
 * @default []
 */
    downloadFieldNames: string[];
/**
 * Options
 * @default {}
 */
    options?: {
    /** The view to operate on. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @searchListMethod getViews
     * @default {"mode":"list","value":""}
     */
    viewId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
    /** The select fields of the returned rows
     * @loadOptionsMethod getFields
     * @default []
     */
    fields?: string[];
    /** The sorting rules for the returned rows
     * @default {}
     */
    sort?: {
        /** Property
     */
    property?: Array<{
      /** Name of the field to sort on
       * @searchListMethod getFields
       * @default {"mode":"list","value":""}
       */
      field?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
      /** The sort direction
       * @default asc
       */
      direction?: 'asc' | 'desc' | Expression<string>;
    }>;
  };
    /** A formula used to filter rows
     */
    where?: string | Expression<string>;
    /** The number of pages to skip from the beginning
     */
    page?: number | Expression<number>;
    /** Whether to shuffle the results
     * @default false
     */
    shuffle?: boolean | Expression<boolean>;
  };
};

export type NocoDbV4RowSearchNode = {
  type: 'n8n-nodes-base.nocoDb';
  version: 4;
  config: NodeConfig<NocoDbV4RowSearchParams> & { credentials?: Credentials };
};